+const navToggle = document.querySelector(".nav-toggle");
+const navLinks = document.querySelector(".nav-links");
+const cartLink = document.querySelector(".cart-link span");
+const cartButtons = document.querySelectorAll(".add-to-cart, .icon-button");
+const signupForm = document.querySelector(".signup-form");
+const formMessage = document.querySelector(".form-message");
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+  navToggle.setAttribute("aria-expanded", String(!isOpen));
+  navLinks.classList.toggle("is-open", !isOpen);
+  document.body.classList.toggle("menu-open", !isOpen);
+});
+
+navLinks.addEventListener("click", (event) => {
+  if (event.target instanceof HTMLAnchorElement) {
+    navToggle.setAttribute("aria-expanded", "false");
+    navLinks.classList.remove("is-open");
+    document.body.classList.remove("menu-open");
+  }
+});
+
+cartButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const currentCount = Number(cartLink.textContent);
+    cartLink.textContent = String(currentCount + 1);
+    button.textContent = button.classList.contains("icon-button") ? "✓" : "Added";
+    button.setAttribute("aria-label", "Added to cart");
+    button.disabled = true;
+  });
+});
+
+signupForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const formData = new FormData(signupForm);
+  const email = String(formData.get("email") || "").trim();
+
+  if (!email) {
+    formMessage.textContent = "Enter an email address to join.";
+    return;
+  }
+
+  formMessage.textContent = "You're in. Watch your inbox for the next private edit.";
+  signupForm.reset();
+});
